std::string s = "ABCDEFGHIJ";
std::string r = "12345";

// Target range s[2] to s[6] ('CDEF') - Length 4

// Optimization: In-Place Replacement (Length Check)
// If Target Length == Replacement Length (e.g., 4)
// Avoids internal memory shift/reallocation.
s.replace(s.begin() + 2, s.begin() + 6,
          r.begin(), r.begin() + 4); // Uses "1234" (Length 4)

// Standard Behavior: Potential Reallocation/Data Shift
// If Target Length < Replacement Length (e.g., 5 vs 4)
// Requires moving subsequent data (GHIJ) and possible realloc.
s.replace(s.begin() + 2, s.begin() + 6,
          r.begin(), r.end());      // Uses "12345" (Length 5)
